// Where Vipassana's character is solid, as 87 x 103 bits of his picture, for pressing him (see scripts/make-character-mask.mjs,
// which writes this file: do not edit it by hand). Read from the picture at runtime it came back blank or with noise in Safari.
export const MASK_W = 87;
export const MASK_H = 103;
const bytes = Uint8Array.from(atob(''), (c) => c.charCodeAt(0));
export const solidAt = (x, y) => x >= 0 && y >= 0 && x < MASK_W && y < MASK_H && ((bytes[(y * MASK_W + x) >> 3] >> (7 - ((y * MASK_W + x) & 7))) & 1) === 1;
